CREATE TABLE "PostingLink" ("id" SERIAL PRIMARY KEY, "token" TEXT NOT NULL UNIQUE, "label" TEXT NOT NULL, "ownerId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PropertySubmission" ("propertyId" INTEGER PRIMARY KEY REFERENCES "Property"("id") ON DELETE CASCADE, "linkId" INTEGER NOT NULL REFERENCES "PostingLink"("id"), "name" TEXT NOT NULL, "phone" TEXT NOT NULL, "email" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
